static void require(bool ok,const char*message){if(!ok)throw std::runtime_error(message);}
static std::vector<uint32_t>capture(HWND window){RECT rect{};GetClientRect(window,&rect);int width=int(rect.right),height=int(rect.bottom);auto source=GetDC(window),memory=CreateCompatibleDC(source);auto bitmap=CreateCompatibleBitmap(source,width,height);auto previous=SelectObject(memory,bitmap);require(BitBlt(memory,0,0,width,height,source,0,0,SRCCOPY)!=FALSE,"capture rendered client");SelectObject(memory,previous);BITMAPINFO info{};info.bmiHeader.biSize=sizeof(BITMAPINFOHEADER);info.bmiHeader.biWidth=width;info.bmiHeader.biHeight=-height;info.bmiHeader.biPlanes=1;info.bmiHeader.biBitCount=32;info.bmiHeader.biCompression=BI_RGB;std::vector<uint32_t>pixels(size_t(width)*height);int lines=GetDIBits(memory,bitmap,0,UINT(height),pixels.data(),&info,DIB_RGB_COLORS);DeleteObject(bitmap);DeleteDC(memory);ReleaseDC(window,source);require(lines==height,"native pixels read");for(auto&pixel:pixels)pixel&=0xffffff;return pixels;}
